package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.crew.CrewRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.role.StewardOnlyException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Merges the person into another on the sheet (a steward): not themselves, and neither retired. Their
 * claims move to the other (numbers and dates kept, listed after the other's in the order they were
 * added, each keeping any figure a statement bound it to); their statement count is added to the other's
 * (whose last statement stays theirs, or, having none, becomes this person's); their name and aliases become the other's
 * aliases; their patrons, pool and crew memberships (and a crew they lead) go to the other, and anyone naming them as patron names
 * the other instead. Their holds, watchers and contact are dropped, and they leave the list.
 */
public class MergePerson {
    public void merge(@Val MergeInput input, @Val Sheet sheet, @Val Person person, PersonRepository people,
            ClaimRepository claims, PoolRepository pools, CrewRepository crews, RoleRepository roles, HttpServletRequest request,
            Out<Merge> mergeOut) throws StewardOnlyException, InvalidPersonException {
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), Audit.user(request)))) {
            throw new StewardOnlyException("Only a steward may merge people");
        }
        Person into = people.find(sheet.id(), input.intoId());
        if (into == null) throw new InvalidPersonException("No such person to merge into");
        if (into.getId().equals(person.getId())) throw new InvalidPersonException("A person cannot be merged into themselves");
        if (person.isRetired() || into.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        List<Claim> moving = new ArrayList<>(claims.findByPerson(sheet.id(), person.getId()));
        Collections.reverse(moving);
        for (Claim claim : moving) {
            claim.mergeTo(into.getId());
            claims.save(claim);
        }
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Opens the claim, recording the signed-in user who opened it. Only a role the permission matrix allows may open. A
 * claim whose due is above the note threshold in force on its date is refused while its note is empty. A claim
 * whose due is above the review threshold in force on its date goes to REVIEW instead, still recording who opened it.
 */
public class OpenClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, RoleRepository roles, SettingsRepository settings,
            PersonRepository people, RateRepository rates, HttpServletRequest request) throws InvalidClaimStatusException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.find(sheet.id()).allows("open", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not open a claim");
        }
        if (needsNote(sheet, claim, people, rates, settings)) throw new InvalidClaimStatusException(NoteRequired.MESSAGE);
        claim.moveTo(opensTo(sheet, claim, people, rates, settings));
        claim.setOpenedBy(user);
    }

    /**
     * The status a DRAFT claim moves to when it is opened: REVIEW when its due, as it stands before it is
     * opened, is above the review threshold in force on its date, else OPEN. Any other claim cannot be opened.
     */
    static ClaimStatus opensTo(Sheet sheet, Claim claim, PersonRepository people, RateRepository rates,
            SettingsRepository settings) throws InvalidClaimStatusException {
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.OPEN);
        return settings.find(sheet.id()).needsReview(LogClaimStatus.due(sheet, claim, people, rates, settings),
                claim.getDate()) ? ClaimStatus.REVIEW : ClaimStatus.OPEN;
    }

    /** Whether the claim's due, as it stands before it is opened, needs a note it does not have. */
    static boolean needsNote(Sheet sheet, Claim claim, PersonRepository people, RateRepository rates,
            SettingsRepository settings) {
        return settings.find(sheet.id()).needsNote(LogClaimStatus.due(sheet, claim, people, rates, settings),
                claim.getDate(), claim.getNote());
    }
}
# Open the selected claims together, in list order. Each that cannot be opened is refused and left
# as it is; the response tells how many were opened and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: open
# Each claim opened is audited as it is opened: its own line, then the figures it moved.
open:
  class: net.officefloor.hq.app.claim.OpenSelectedClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]
# Paste claims: a claim per line of name,amount,date,note for the named person, in order, each added
# (or a matching DRAFT updated) and opened as the open button opens it. One change: every line is
# checked before anything is written, and a refused line or open refuses the whole paste (a bad line
# is a 400, a refused open a 409).
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.paste.ValidatePaste
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: add
# Checks every line, then saves, opens and audits each claim in order, each followed by the figures it moved.
add:
  class: net.officefloor.hq.app.claim.AddPastedClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.paste.RespondWithPaste
  govern: [ transaction ]

